{"security_risk":"LOW","summary":"Create protocol module","command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/protocol.rs","file_text":"//! Wire protocol shared by the Rust runner and the JS bridge (`bridge/transform-host.js`).
//!
//! The runner sends `{files, options}` JSON messages to workers and receives
//! `{action: ...}` JSON messages back. All numeric/string fields mirror the
//! upstream jscodeshift message format so the JS bridge can stay small.

use serde::{Deserialize, Serialize};

/// Request payload sent from the runner to each worker.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WorkRequest {
    pub files: Vec<String>,
    /// Run options echoed to the worker; see `Options` in `args.rs`.
    #[serde(default)]
    pub options: serde_json::Value,
}

/// Status types reported back from the worker.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum FileStatus {
    Ok,
    Error,
    Nochange,
    Skip,
}

/// Messages emitted by the worker.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerMessage {
    /// Mark a file as processed.
    #[serde(rename = "status")]
    Status {
        status: FileStatus,
        msg: String,
    },
    /// Increment a named counter (for `stats` reporting).
    #[serde(rename = "update")]
    Update { name: String, quantity: u64 },
    /// Worker is free and ready for more work.
    #[serde(rename = "free")]
    Free,
    /// Free-form report from the transform.
    #[serde(rename = "report")]
    Report { file: String, msg: String },
}

/// Final aggregated result printed by the runner.
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct RunResult {
    pub ok: u64,
    pub error: u64,
    pub nochange: u64,
    pub skip: u64,
    #[serde(default)]
    pub stats: serde_json::Value,
    pub time_elapsed: f64,
}

impl RunResult {
    pub fn fail_on_error(&self, fail_on_error: bool) -> bool {
        fail_on_error && self.error > 0
    }
}"}

{"security_risk":"LOW","summary":"Create args module","command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/args.rs","file_text":"//! CLI argument parsing for `jscodeshift-core`.
//!
//! The argument surface mirrors the upstream jscodeshift 17.4.0
//! `argsParser`/`bin/jscodeshift.js` definitions so that user-visible
//! behavior (flag names, defaults, help text, validation, exit codes)
//! is preserved exactly.

use clap::{Arg, ArgAction, ArgMatches, Command};
use serde::Serialize;
use std::collections::HashMap;
use std::path::Path;
use std::process::ExitCode;

/// All available parser backends.
pub const PARSER_CHOICES: &[&str] = &["babel", "babylon", "flow", "ts", "tsx"];

/// CLI exit codes matching upstream behavior.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExitCodeKind {
    Ok = 0,
    Usage = 1,
}

/// Options consumed by the runner; this struct is serialized and sent to
/// each worker via the `options` field of `WorkRequest`.
#[derive(Debug, Clone, Serialize)]
pub struct RunOptions {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: Vec<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<serde_json::Value>,
    pub fail_on_error: bool,
    pub stdin: bool,

    /// Bag of unknown options (forwarded to transforms).
    #[serde(flatten)]
    pub extra: HashMap<String, serde_json::Value>,
}

impl RunOptions {
    /// Parse extensions string ("js,ts,tsx") into a sorted Vec of "js"/"ts"/...
    pub fn parsed_extensions(&self) -> Vec<String> {
        let mut out: Vec<String> = self
            .extensions
            .iter()
            .flat_map(|s| s.split(','))
            .map(|s| s.trim().trim_start_matches('.').to_string())
            .filter(|s| !s.is_empty())
            .collect();
        out.sort();
        out.dedup();
        out
    }
}

/// Parsed result of `parse_args` — options plus remaining positional paths.
#[derive(Debug)]
pub struct ParsedArgs {
    pub options: RunOptions,
    pub positional: Vec<String>,
    pub help_text: String,
}

fn default_extensions_string() -> String {
    // Mirror upstream:
    //   DEFAULT_EXTENSIONS = ['.js', '.jsx', '.mjs', '.cjs']
    //   concat(['ts', 'tsx']) -> ['.js', '.jsx', '.mjs', '.cjs', '.ts', '.tsx']
    //   strip leading '.', sort, join(',')
    let mut exts: Vec<String> = vec![
        "js".into(),
        "jsx".into(),
        "mjs".into(),
        "cjs".into(),
        "ts".into(),
        "tsx".into(),
    ];
    exts.sort();
    exts.join(",")
}

pub fn build_cli() -> Command {
    let exts = default_extensions_string();
    Command::new("jscodeshift-core")
        .bin_name("jscodeshift")
        .about("A toolkit for JavaScript codemods (native core)")
        .override_usage(
            "Usage: jscodeshift [OPTION]... PATH...\n  \
             or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  \
             or:  jscodeshift [OPTION]... -t URL PATH...\n  \
             or:  jscodeshift [OPTION]... --stdin < file_list.txt",
        )
        .arg(
            Arg::new("transform")
                .short('t')
                .long("transform")
                .value_name("FILE")
                .help("path to the transform file. Can be either a local path or url")
                .required(true)
                .num_args(1),
        )
        .arg(
            Arg::new("cpus")
                .short('c')
                .long("cpus")
                .value_name("N")
                .help("start at most N child processes to process source files")
                .num_args(1)
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .value_name("N")
                .help("show more information about the transform process")
                .value_parser(clap::value_parser!(u8)),
        )
        .arg(
            Arg::new("dry")
                .short('d')
                .long("dry")
                .help("dry run (no changes are made to files)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("print")
                .short('p')
                .long("print")
                .help("print transformed files to stdout, useful for development")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("babel")
                .long("babel")
                .help("apply babeljs to the transform file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-babel")
                .long("no-babel")
                .help("disable babeljs for the transform file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("extensions")
                .long("extensions")
                .value_name("EXT")
                .help("transform files with these file extensions (comma separated list)")
                .default_value(exts),
        )
        .arg(
            Arg::new("ignore-pattern")
                .long("ignore-pattern")
                .value_name("GLOB")
                .help("ignore files that match a provided glob expression")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("ignore-config")
                .long("ignore-config")
                .value_name("FILE")
                .help("ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)")
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("gitignore")
                .long("gitignore")
                .help("adds entries the current directory's .gitignore file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("run-in-band")
                .long("run-in-band")
                .help("run serially in the current process")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("silent")
                .short('s')
                .long("silent")
                .help("do not write to stdout or stderr")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("parser")
                .long("parser")
                .value_name("PARSER")
                .help("the parser to use for parsing the source files")
                .value_parser(clap::builder::PossibleValuesParser::new(PARSER_CHOICES))
                .default_value("babel"),
        )
        .arg(
            Arg::new("parser-config")
                .long("parser-config")
                .value_name("FILE")
                .help("path to a JSON file containing a custom parser configuration for flow or babylon")
                .num_args(1),
        )
        .arg(
            Arg::new("fail-on-error")
                .long("fail-on-error")
                .help("Return a non-zero code when there are errors")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("version")
                .long("version")
                .help("print version and exit")
                .action(ArgAction::Version),
        )
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .help("print this help and exit")
                .action(ArgAction::Help),
        )
        .arg(
            Arg::new("stdin")
                .long("stdin")
                .help("read file/directory list from stdin")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("PATH")
                .help("files or directories to transform")
                .num_args(0..)
                .value_parser(clap::value_parser!(String)),
        )
        .disable_help_flag(true)
        .disable_version_flag(true)
}

pub fn help_text(cmd: &Command) -> String {
    let mut buf: Vec<u8> = Vec::new();
    cmd.clone().write_help(&mut buf).expect("write help");
    String::from_utf8(buf).unwrap_or_default()
}

fn load_parser_config(path: &str) -> Result<serde_json::Value, String> {
    let data = std::fs::read_to_string(path)
        .map_err(|e| format!("Could not read parser-config file {path}: {e}"))?;
    serde_json::from_str(&data)
        .map_err(|e| format!("Could not parse parser-config file {path} as JSON: {e}"))
}

/// Parse CLI arguments. The returned `RunOptions` is in a normalized form
/// that the runner and worker both consume.
pub fn parse_args<I, T>(args: I) -> Result<ParsedArgs, String>
where
    I: IntoIterator<Item = T>,
    T: Into<std::ffi::OsString> + Clone,
{
    let cmd = build_cli();
    let matches: ArgMatches = cmd
        .clone()
        .try_get_matches_from(args)
        .map_err(|e| format!("{e}"))?;

    let transform = matches
        .get_one::<String>("transform")
        .cloned()
        .unwrap_or_else(|| "./transform.js".into());

    let cpus = matches.get_one::<usize>("cpus").copied();
    let verbose = matches.get_one::<u8>("verbose").copied().unwrap_or(0);
    let dry = matches.get_flag("dry");
    let print = matches.get_flag("print");
    let babel = if matches.get_flag("no-babel") {
        false
    } else {
        matches.get_flag("babel")
    };
    let extensions = matches
        .get_one::<String>("extensions")
        .cloned()
        .unwrap_or_else(default_extensions_string);
    let ignore_pattern: Vec<String> = matches
        .get_many::<String>("ignore-pattern")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let ignore_config: Vec<String> = matches
        .get_many::<String>("ignore-config")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let gitignore = matches.get_flag("gitignore");
    let run_in_band = matches.get_flag("run-in-band");
    let silent = matches.get_flag("silent");
    let parser = matches
        .get_one::<String>("parser")
        .cloned()
        .unwrap_or_else(|| "babel".into());
    let parser_config = match matches.get_one::<String>("parser-config") {
        Some(p) => Some(load_parser_config(p)?),
        None => None,
    };
    let fail_on_error = matches.get_flag("fail-on-error");
    let stdin = matches.get_flag("stdin");

    let positional: Vec<String> = matches
        .get_many::<String>("PATH")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    // Drop any flags the runner consumed; everything else becomes "extra"
    // and is forwarded to transforms.
    let known_ids: std::collections::HashSet<&'static str> = [
        "transform",
        "cpus",
        "verbose",
        "dry",
        "print",
        "babel",
        "no-babel",
        "extensions",
        "ignore-pattern",
        "ignore-config",
        "gitignore",
        "run-in-band",
        "silent",
        "parser",
        "parser-config",
        "fail-on-error",
        "version",
        "help",
        "stdin",
        "PATH",
    ]
    .into_iter()
    .collect();

    let mut extra = HashMap::new();
    for id in matches.ids() {
        let key = id.to_string();
        if known_ids.contains(key.as_str()) {
            continue;
        }
        if let Some(values) = matches.get_many::<String>(&key) {
            let collected: Vec<String> = values.cloned().collect();
            let v = if collected.len() == 1 {
                serde_json::Value::String(collected.into_iter().next().unwrap())
            } else {
                serde_json::Value::Array(
                    collected.into_iter().map(serde_json::Value::String).collect(),
                )
            };
            extra.insert(key, v);
        } else if matches.get_flag(&key) {
            extra.insert(key, serde_json::Value::Bool(true));
        }
    }

    let options = RunOptions {
        transform,
        cpus,
        verbose,
        dry,
        print,
        babel,
        extensions,
        ignore_pattern,
        ignore_config,
        gitignore,
        run_in_band,
        silent,
        parser,
        parser_config,
        fail_on_error,
        stdin,
        extra,
    };

    Ok(ParsedArgs {
        options,
        positional,
        help_text: help_text(&cmd),
    })
}

/// Helper used by tests/CLI dispatching to format an error.
pub fn usage_error(msg: &str, help: &str) -> String {
    if help.is_empty() {
        msg.to_string()
    } else {
        format!("{msg}\n\n---\n\n{help}")
    }
}

/// Returns true if `path` looks like an HTTP(S) URL.
pub fn is_http_url(path: &str) -> bool {
    path.starts_with("http://") || path.starts_with("https://")
}

/// Returns true if `path` exists on disk.
pub fn path_exists(path: impl AsRef<Path>) -> bool {
    path.as_ref().exists()
}

/// Entry-point used by `main.rs`. Translates `parse_args` failure to a clean
/// exit code.
pub fn parse_args_or_exit<I, T>(args: I) -> Result<ParsedArgs, (ExitCode, String)>
where
    I: IntoIterator<Item = T>,
    T: Into<std::ffi::OsString> + Clone,
{
    match parse_args(args) {
        Ok(p) => Ok(p),
        Err(e) => Err((ExitCode::from(ExitCodeKind::Usage as u8), e)),
    }
}"}

{"security_risk":"LOW","summary":"Create ignore module","command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/ignore.rs","file_text":"//! Glob-based ignore matcher.
//!
//! Mirrors `src/ignoreFiles.js`: globs are translated into the three
//! equivalents the upstream code adds (`**/pat`, `pat`, and the trailing-/
//! `**` variants), then matched with the `globset` crate which has
//! identical semantics to the `picomatch` crate used by upstream.

use globset::{Glob, GlobMatcher};
use std::fs;
use std::path::Path;

/// Holds the set of compiled ignore matchers.
#[derive(Debug, Default)]
pub struct IgnoreSet {
    matchers: Vec<GlobMatcher>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        Self::default()
    }

    /// Add one or many patterns (string or &str).
    pub fn add<I, S>(&mut self, patterns: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for raw in patterns {
            self.add_one(raw.as_ref());
        }
    }

    fn add_one(&mut self, raw: &str) {
        // Skip comments and blanks.
        let val = raw.trim();
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        if let Some(matcher) = compile_pattern(val) {
            self.matchers.push(matcher);
        }
    }

    /// Add patterns from a config file (e.g. .gitignore). One per line.
    pub fn add_from_file(&mut self, path: &Path) {
        let Ok(content) = fs::read_to_string(path) else {
            return;
        };
        for line in content.split('\n') {
            // Strip trailing \r for CRLF files.
            let line = line.trim_end_matches('\r');
            self.add_one(line);
        }
    }

    /// Test whether `path` should be ignored.
    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        if self.any_match(path) {
            return true;
        }
        // Strip leading `./` or `../` traversals so that patterns like
        // `**/node_modules/**` continue to match relative input paths.
        let stripped = path
            .trim_start_matches("./")
            .trim_start_matches("../");
        if stripped != path && self.any_match(stripped) {
            return true;
        }
        false
    }

    fn any_match(&self, path: &str) -> bool {
        // Trim trailing slashes (a directory listing may include `dir/`).
        let trimmed = path.trim_end_matches('/');
        self.matchers.iter().any(|m| m.is_match(trimmed))
    }
}

/// Translate a single pattern into a compiled matcher, replicating the
/// translation done in `src/ignoreFiles.js`:
///   - patterns containing `/` get added as-is
///   - patterns *not* containing `/` are also added as `**/pattern`
///   - trailing-`/` patterns get `**/pattern/**` and `pattern/**` variants
fn compile_pattern(pat: &str) -> Option<GlobMatcher> {
    let mut out = Vec::new();
    if !pat.contains('/') {
        out.push(format!("**/{pat}"));
    } else if pat.ends_with('/') {
        out.push(format!("**/{pat}**"));
        out.push(format!("{pat}**"));
    }
    out.push(pat.to_string());

    let last = out.last().cloned()?;
    // The first matcher that compiles wins; fall back to building a
    // best-effort matcher from the trailing pattern.
    for candidate in &out {
        if let Ok(g) = Glob::new(candidate) {
            return Some(g.compile_matcher());
        }
    }
    Glob::new(&last).ok().map(|g| g.compile_matcher())
}"}

{"security_risk":"LOW","summary":"Create files module","command":"create","path":"/workspace/codebase/crates/jscodeshift-core/src/files.rs","file_text":"//! File discovery.
//!
//! Replicates the behavior of `dirFiles` / `getAllFiles` in `src/Runner.js`:
//! each input path is either treated as a directory (recursively walked) or
//! as a single file. Hidden files are skipped by `walkdir` by default but
//! patterns like `**/node_modules` still match thanks to the `IgnoreSet`.

use crate::ignore::IgnoreSet;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

/// Return all files under `roots` that have an extension listed in
/// `extensions` (each entry including its leading dot) and are not matched
/// by `ignore_set`. Mirrors upstream `getAllFiles`.
pub fn collect_files<P, S>(roots: &[P], extensions: &[S], ignore_set: &IgnoreSet) -> Vec<PathBuf>
where
    P: AsRef<Path>,
    S: AsRef<str>,
{
    let mut files: Vec<PathBuf> = Vec::new();
    let mut dirs: Vec<PathBuf> = Vec::new();

    for root in roots {
        let path = root.as_ref();
        let md = match std::fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path {} which does not exist.", path.display());
                continue;
            }
        };
        if md.is_dir() {
            dirs.push(path.to_path_buf());
        } else {
            files.push(path.to_path_buf());
        }
    }

    let mut walked: Vec<PathBuf> = Vec::new();
    for dir in &dirs {
        for entry in WalkDir::new(dir).into_iter().filter_entry(|e| {
            let s = e.path().to_string_lossy().to_string();
            !ignore_set.should_ignore(&s)
        }) {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            if !entry.file_type().is_file() {
                continue;
            }
            walked.push(entry.into_path());
        }
    }

    let by_ext = |p: &PathBuf| -> bool {
        if extensions.is_empty() {
            return true;
        }
        match p.extension().and_then(|e| e.to_str()) {
            Some(ext) => {
                let dotted = format!(".{ext}");
                extensions.iter().any(|e| e.as_ref() == dotted)
            }
            None => false,
        }
    };

    let mut result: Vec<PathBuf> = files
        .into_iter()
        .filter(|p| !ignore_set.should_ignore(&p.to_string_lossy()))
        .filter(&by_ext)
        .collect();
    result.extend(walked.into_iter().filter(&by_ext));
    result.sort();
    result
}

/// Split `files` into `n` roughly-equal chunks for worker dispatch.
pub fn chunk<T: Clone>(files: Vec<T>, n: usize) -> Vec<Vec<T>> {
    if n == 0 || files.is_empty() {
        return vec![files];
    }
    let chunk_size = std::cmp::max(1, (files.len() + n - 1) / n);
    let mut chunks: Vec<Vec<T>> = Vec::new();
    let mut iter = files.into_iter();
    loop {
        let mut current: Vec<T> = Vec::with_capacity(chunk_size);
        for _ in 0..chunk_size {
            if let Some(v) = iter.next() {
                current.push(v);
            } else {
                break;
            }
        }
        if current.is_empty() {
            break;
        }
        chunks.push(current);
    }
    chunks
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn chunk_splits_round_robin() {
        let files: Vec<i32> = (0..10).collect();
        let chunks = chunk(files, 3);
        assert_eq!(chunks.len(), 3);
        assert_eq!(chunks[0].len(), 4);
        assert_eq!(chunks[1].len(), 3);
        assert_eq!(chunks[2].len(), 3);
    }

    #[test]
    fn chunk_empty() {
        let chunks: Vec<Vec<i32>> = chunk(vec![], 4);
        assert_eq!(chunks.len(), 0);
    }
}"}

{"security_risk":"LOW","summary":"Create JS bridge","command":"create","path":"/workspace/codebase/bridge/transform-host.js","file_text":"// bridge/transform-host.js
//
// Thin Node.js worker bridge used by the Rust `jscodeshift-core` runner.
// Each worker process receives a single {files, options} JSON message on
// stdin (terminated by EOF), runs the user's transform against each file
// via the upstream jscodeshift public API, and emits progress events on
// stdout as line-delimited JSON.
//
// The protocol mirrors what the upstream `src/Worker.js` sent over IPC:
//   {action: 'status',  status: 'ok'|'error'|'nochange'|'skip', msg: '...'}
//   {action: 'update',  name: '...', quantity: N}
//   {action: 'free'}
//   {action: 'report',  file: '...', msg: '...'}
//
// The Rust runner reads one JSON object per line from the worker's stdout
// until the worker exits, so we keep messages small and on single lines.

'use strict';

const fs = require('fs');
const path = require('path');
const EventEmitter = require('events');

const async = require('neo-async');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const jscodeshift = require(path.resolve(__dirname, '..', 'src', 'core'));
const getParser = require(path.resolve(__dirname, '..', 'src', 'getParser'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

function logEvent(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  for (const line of lines) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
    }
  }
  return result.join('\n');
