//! stdin receives `{files, options}` JSON lines and stdout emits
//! `{action, ...}` JSON lines (parsed by `protocol::WorkerMessage`).

use crate::protocol::{FileStatus, WorkRequest, WorkerMessage};
use crate::RunOptions;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

/// Find the Node.js interpreter the way npm/npx does.
fn find_node() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("JSCODESHIFT_NODE") {
        let path = PathBuf::from(p);
        if path.exists() {
            return Some(path);
        }
    }
    // Try `which node`.
    if let Ok(out) = Command::new("which").arg("node").output() {
        if out.status.success() {
            let p = String::from_utf8_lossy(&out.stdout).trim().to_string();
            if !p.is_empty() {
                return Some(PathBuf::from(p));
            }
        }
    }
    // Hardcoded fallbacks.
    for candidate in [
        "/usr/bin/node",
        "/usr/local/bin/node",
        "/opt/node/bin/node",
    ] {
        let p = PathBuf::from(candidate);
        if p.exists() {
            return Some(p);
        }
    }
    None
}

/// Find the bridge script path. Looks for `bridge/transform-host.js`
/// next to the package root, then a few known fallbacks.
fn find_bridge() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("JSCODESHIFT_BRIDGE") {
        let path = PathBuf::from(p);
        if path.exists() {
            return Some(path);
        }
    }
    // The package root can be inferred from the executable path: the
    // binary lives at `<pkg>/bin/jscodeshift-core` after `build.sh`.
    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            for candidate in [
                parent.join("..").join("bridge").join("transform-host.js"),
                parent.join("bridge").join("transform-host.js"),
                parent
                    .join("..")
                    .join("..")
                    .join("bridge")
                    .join("transform-host.js"),
            ] {
                if candidate.exists() {
                    return Some(candidate);
                }
            }
        }
    }
    None
}

/// A live worker handle. Wraps a `Child` process plus its stdio.
pub struct Worker {
    pub id: usize,
    child: Child,
    stdin: Option<ChildStdin>,
    stdout: BufReader<ChildStdout>,
    transform_path: String,
}

impl Worker {
    /// Spawn a new worker process running `bridge/transform-host.js`.
    pub fn spawn(id: usize, transform_path: &str, options: &RunOptions) -> std::io::Result<Self> {
        let node = find_node().ok_or_else(|| {
            std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "Could not find the `node` executable on PATH",
            )
        })?;
        let bridge = find_bridge().ok_or_else(|| {
            std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "Could not locate bridge/transform-host.js",
            )
        })?;

        let babel_flag = if options.babel { "babel" } else { "no-babel" };

        let mut cmd = Command::new(node);
        cmd.arg(&bridge)
            .arg(transform_path)
            .arg(babel_flag)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        // Hide child stderr unless verbose.
        if options.verbose < 2 {
            cmd.stderr(Stdio::null());
        }

        let mut child = cmd.spawn()?;
        let stdin = child.stdin.take().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::Other, "child stdin unavailable")
        })?;
        let stdout = child.stdout.take().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::Other, "child stdout unavailable")
        })?;
        Ok(Self {
            id,
            child,
            stdin: Some(stdin),
            stdout: BufReader::new(stdout),
            transform_path: transform_path.to_string(),
        })
    }

    /// Send a batch of files to the worker.
    pub fn send(&mut self, req: &WorkRequest) -> std::io::Result<()> {
        if let Some(stdin) = self.stdin.as_mut() {
            let json = serde_json::to_string(req).map_err(|e| {
                std::io::Error::new(std::io::ErrorKind::InvalidInput, e)
            })?;
            stdin.write_all(json.as_bytes())?;
            stdin.write_all(b"\n")?;
            stdin.flush()?;
        }
        Ok(())
    }

    /// Read the next message from the worker's stdout. Returns `Ok(None)`
    /// when the worker has closed its stdout (i.e. exited).
    pub fn recv(&mut self) -> std::io::Result<Option<WorkerMessage>> {
        let mut line = String::new();
        let n = self.stdout.read_line(&mut line)?;
        if n == 0 {
            return Ok(None);
        }
        let trimmed = line.trim();
        if trimmed.is_empty() {
            // Recurse — try to get the next non-empty line.
            return self.recv();
        }
        match serde_json::from_str::<WorkerMessage>(trimmed) {
            Ok(msg) => Ok(Some(msg)),
            Err(e) => {
                // Forward parse errors as file-scoped error events so the
                // caller can decide how to surface them.
                Ok(Some(WorkerMessage::Status {
                    status: FileStatus::Error,
                    msg: format!("worker {} emitted invalid JSON: {}", self.id, e),
                }))
            }
        }
    }

    /// Wait for the child to exit, returning its exit status.
    pub fn wait(&mut self) -> std::io::Result<std::process::ExitStatus> {
        // Drop stdin first so the child sees EOF and exits cleanly.
        self.stdin.take();
        self.child.wait()
    }

    /// Wait for the child to exit, with timeout (seconds).
    pub fn wait_timeout(
        &mut self,
        secs: u64,
    ) -> std::io::Result<Option<std::process::ExitStatus>> {
        // Drop stdin so the child sees EOF.
        self.stdin.take();
        let start = std::time::Instant::now();
        loop {
            match self.child.try_wait()? {
                Some(status) => return Ok(Some(status)),
                None => {
                    if start.elapsed().as_secs() >= secs {
                        return Ok(None);
                    }
                    std::thread::sleep(std::time::Duration::from_millis(50));
                }
            }
        }
    }

    pub fn kill(&mut self) -> std::io::Result<()> {
        let _ = self.child.kill();
        let _ = self.child.wait();
        Ok(())
    }

    pub fn transform_path(&self) -> &str {
        &self.transform_path
    }
}"}

