use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

/// Resolve the transform file path. For local paths, callers should pass
/// `cwd`. The result is the absolute path that the JS bridge will
/// `require()`.
pub fn resolve_transform(transform: &str, cwd: &Path) -> Option<String> {
    let p = PathBuf::from(transform);
    let abs: PathBuf = if p.is_absolute() {
        p
    } else {
        cwd.join(p)
    };
    if abs.exists() {
        return Some(abs.to_string_lossy().to_string());
    }
    // URL form: leave as-is for the bridge to handle (HTTP transform
    // support is mirrored from the upstream runner).
    if transform.starts_with("http://") || transform.starts_with("https://") {
        return Some(transform.to_string());
    }
    None
}

/// Helper used to print a human-readable list of ignored files to stderr
/// during verbose runs.
pub fn print_ignored(ignored: &[String]) {
    if ignored.is_empty() {
        return;
    }
    let mut stderr = std::io::stderr().lock();
    for f in ignored {
        let _ = writeln!(stderr, "ignored: {}", f);
    }
}

/// Counter bundle used by `run`.
struct Counters {
    ok: AtomicU64,
    error: AtomicU64,
    nochange: AtomicU64,
    skip: AtomicU64,
}

impl Counters {
    fn new() -> Self {
        Self {
            ok: AtomicU64::new(0),
            error: AtomicU64::new(0),
            nochange: AtomicU64::new(0),
            skip: AtomicU64::new(0),
        }
    }
    fn add(&self, status: FileStatus) {
        match status {
            FileStatus::Ok => self.ok.fetch_add(1, Ordering::SeqCst),
            FileStatus::Error => self.error.fetch_add(1, Ordering::SeqCst),
            FileStatus::Nochange => self.nochange.fetch_add(1, Ordering::SeqCst),
            FileStatus::Skip => self.skip.fetch_add(1, Ordering::SeqCst),
        };
    }
    fn snapshot(&self) -> (u64, u64, u64, u64) {
        (
            self.ok.load(Ordering::SeqCst),
            self.error.load(Ordering::SeqCst),
            self.nochange.load(Ordering::SeqCst),
            self.skip.load(Ordering::SeqCst),
        )
    }
}

/// Reusable colorizer (cheap to construct, mirrors picocolors semantics).
struct Colorizer;

impl Colorizer {
    fn green(s: &str) -> String {
        format!("\x1b[32m{}\x1b[39m", s)
    }
    fn red(s: &str) -> String {
        format!("\x1b[31m{}\x1b[39m", s)
    }
    fn gray(s: &str) -> String {
        format!("\x1b[90m{}\x1b[39m", s)
    }
}

/// Format the final summary line for a run (e.g. `All done. 4 errors, 3 ok`).
fn format_summary(ok: u64, error: u64, nochange: u64, skip: u64) -> String {
    let mut pieces: Vec<String> = Vec::new();
    if error > 0 {
        pieces.push(format!("{} error{}", error, if error == 1 { "" } else { "s" }));
    }
    if nochange > 0 {
        pieces.push(format!(
            "{} unchanged",
            if nochange == 1 { "skipped" } else { nochange }
        ));
        pieces.truncate(pieces.len() - 1);
    }
    pieces.push(format!(
        "{} ok, {} skipped",
        ok,
        skip
    ));
    let body = pieces.join(", ");
    if error > 0 {
        Colorizer::red(&format!("All done. {}", body))
    } else {
        Colorizer::green(&format!("All done. {}", body))
    }
}

/// Configuration consumed by `run`.
pub struct RunSpec<'a> {
    pub transform: &'a str,
    pub inputs: &'a [PathBuf],
    pub options: &'a RunOptions,
    pub cwd: &'a Path,
}

/// Execute the transform against `inputs`. Returns a `RunResult` with
/// per-status counts and aggregated stats.
pub fn run(spec: RunSpec<'_>) -> Result<RunResult, String> {
    let RunSpec {
        transform,
        inputs,
        options,
        cwd,
    } = spec;

