    let cpu_count = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    let pool_size = if options.run_in_band {
        1
    } else if let Some(n) = options.cpus {
        n.max(1)
    } else {
        cpu_count.max(1)
    };

    let work_chunks: Vec<Vec<PathBuf>> = chunk(files.clone(), pool_size);

    // 5. Spawn workers.
    let mut workers: Vec<Worker> = Vec::with_capacity(pool_size);
    for i in 0..pool_size {
        let w = Worker::spawn(i, &transform_path, options)
            .map_err(|e| format!("Could not spawn worker {i}: {e}"))?;
        workers.push(w);
    }

    // 6. Send initial work to each worker.
    for (i, chunk) in work_chunks.iter().enumerate() {
        let req = WorkRequest {
            files: chunk.iter().map(|p| p.to_string_lossy().to_string()).collect(),
            options: serde_json::to_value(options).unwrap_or_else(|_| json!({})),
        };
        workers[i].send(&req).map_err(|e| format!("worker {i} send failed: {e}"))?;
    }

    // 7. Drain messages until each worker has reported 'free' once.
    let mut remaining_free: Vec<bool> = vec![true; workers.len()];
    let mut all_done = false;
    while !all_done {
        all_done = remaining_free.iter().all(|x| *x);
        if all_done {
