        for (i, w) in workers.iter_mut().enumerate() {
            if remaining_free[i] {
                continue;
            }
            match w.recv() {
                Ok(Some(WorkerMessage::Free)) => {
                    remaining_free[i] = true;
                }
                Ok(Some(WorkerMessage::Status { status, msg })) => {
                    counters.add(status);
