                    let mut s = stats.lock().unwrap();
                    let map = s.as_object_mut().unwrap();
                    let entry = map
                        .entry(name)
                        .or_insert_with(|| serde_json::Value::from(0u64));
                    if let Some(n) = entry.as_u64() {
                        *entry = serde_json::Value::from(n + quantity);
                    } else {
                        *entry = serde_json::Value::from(quantity);
                    }
                }
                Ok(Some(WorkerMessage::Report { file, msg })) => {
                    let mut stderr = std::io::stderr().lock();
                    let _ = writeln!(stderr, "{}", Colorizer::gray(&format!("[{}] {}", file, msg)));
                }
                Ok(None) => {
                    // Worker exited prematurely; mark as free so we don't
                    // wait forever. Continue to drain other workers.
                    remaining_free[i] = true;
                }
                Err(e) => {
                    return Err(format!("worker {i} read error: {e}"));
                }
            }
        }
    }

