    for w in &mut workers {
        let _ = w.wait_timeout(2);
    }

    let elapsed = started.elapsed().as_secs_f64();
    let (ok, error, nochange, skip) = counters.snapshot();
    let result = RunResult {
        ok,
        error,
        nochange,
        skip,
        stats: stats.lock().unwrap().clone(),
        time_elapsed: elapsed,
    };

    if !options.silent {
        let mut stdout = std::io::stdout().lock();
        let _ = writeln!(stdout, "{}", format_summary(ok, error, nochange, skip));
        if !result.stats.is_object() || !result.stats.as_object().unwrap().is_empty() {
            let _ = writeln!(stdout, "Stats: {}", result.stats);
        }
    }

    Ok(result)
}"}

